<?php

use PHPUnit\Framework\TestCase;

class SystemConfigTest extends TestCase {
  function test_writeConfigIni_preserves_password_pattern(): void {
    $configPath = tempnam(sys_get_temp_dir(), 'testcenter-config-');
    if ($configPath === false) {
      throw new RuntimeException('Could not create temporary config file.');
    }
    $originalPattern = SystemConfig::$password_pattern;
    $pattern = '^(?=.*[A-Z])(?=.*[!@#$%^&*]).{12,}$';

    try {
      SystemConfig::$password_pattern = $pattern;
      SystemConfig::writeConfigIni($configPath);

      /** @var array<string, array<string, mixed>>|false $config */
      $config = parse_ini_file($configPath, true, INI_SCANNER_TYPED);
      $this->assertIsArray($config);
      $this->assertSame($pattern, $config['password']['pattern']);
    } finally {
      SystemConfig::$password_pattern = $originalPattern;
      unlink($configPath);
    }
  }
}
